CREATE OR REPLACE FUNCTION zapp.fn_webhook_events_retention()
 RETURNS TABLE(tipo_evento text, qtd_removidos integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'zapp', 'monitoring'
AS $function$
DECLARE v_conn INT; v_upd INT; v_ups INT; v_pres INT; v_other INT;
BEGIN
  WITH d AS (DELETE FROM evolution_webhook_events WHERE event_type='CONNECTION_UPDATE' AND created_at<now()-interval '4 hours' RETURNING 1) SELECT count(*) INTO v_conn FROM d;
  WITH d AS (DELETE FROM evolution_webhook_events WHERE event_type='MESSAGES_UPDATE' AND created_at<now()-interval '24 hours' RETURNING 1) SELECT count(*) INTO v_upd FROM d;
  WITH d AS (DELETE FROM evolution_webhook_events WHERE event_type IN ('MESSAGES_UPSERT','messages.upsert') AND processed=true AND created_at<now()-interval '7 days' RETURNING 1) SELECT count(*) INTO v_ups FROM d;
  WITH d AS (DELETE FROM evolution_webhook_events WHERE event_type IN ('CHATS_UPDATE','CONTACTS_UPDATE','chats.update','contacts.update') AND created_at<now()-interval '48 hours' RETURNING 1) SELECT count(*) INTO v_other FROM d;
  RETURN QUERY VALUES ('CONNECTION_UPDATE'::text,v_conn),('MESSAGES_UPDATE',v_upd),('MESSAGES_UPSERT',v_ups),('OTHERS',v_other);
