=== zapp.get_compliance_metrics(snapshot_time timestamp without time zone) [] SETOF record
CREATE OR REPLACE FUNCTION zapp.get_compliance_metrics(snapshot_time timestamp without time zone DEFAULT now())
 RETURNS TABLE(total_deleted integer, pending_deletion integer, already_anonymized integer, with_lgpd_consent integer, compliance_rate_pct numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'zapp', 'pg_catalog', 'auth'
AS $function$
BEGIN
  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;

  RETURN QUERY
  WITH deleted_contacts AS (
    SELECT id, pii_masked_at, lgpd_consent_at
    FROM zapp.evolution_contacts
    WHERE deleted_at IS NOT NULL
  )
  SELECT 
    COUNT(*)::INT AS total_deleted,
    COUNT(*) FILTER (WHERE pii_masked_at IS NULL)::INT AS pending_deletion,
    COUNT(*) FILTER (WHERE pii_masked_at IS NOT NULL)::INT AS already_anonymized,
    COUNT(*) FILTER (WHERE lgpd_consent_at IS NOT NULL)::INT AS with_consent,
    ROUND(
      COUNT(*) FILTER (WHERE pii_masked_at IS NOT NULL)::NUMERIC / 
      NULLIF(COUNT(*), 0) * 100, 2
    )::NUMERIC AS compliance_rate_pct
  FROM deleted_contacts;
END;
$function$

