=== zapp.get_segment_contacts(p_segment_id uuid, p_limit integer, p_offset integer) [] SETOF record
CREATE OR REPLACE FUNCTION zapp.get_segment_contacts(p_segment_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, remote_jid text, phone_number text, full_name text, push_name text, lead_status text, lead_score integer, last_message_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'zapp', 'monitoring'
AS $function$
DECLARE
  v_filters jsonb; v_instance text; v_lead_status text; v_min_score int;
  v_created_after timestamptz; v_no_consent boolean;
BEGIN
  -- FIX: qualificar contact_segments.id pra evitar ambiguidade com p_segment_id no Self-Hosted
  SELECT cs.filters, cs.instance_name INTO v_filters, v_instance
  FROM zapp.contact_segments cs WHERE cs.id = p_segment_id;

  IF NOT FOUND THEN RETURN; END IF;

  v_lead_status := v_filters->>'lead_status';
  v_min_score := (v_filters->>'min_lead_score')::int;
  v_no_consent := (v_filters->>'no_lgpd_consent')::boolean;

  IF v_filters->>'created_after' = '7d' THEN
    v_created_after := now() - interval '7 days';
  ELSIF v_filters->>'created_after' = '30d' THEN
    v_created_after := now() - interval '30 days';
  END IF;

  RETURN QUERY
  SELECT c.id, c.remote_jid::text, c.phone_number::text,
    c.full_name::text, c.push_name::text,
    c.lead_status::text, c.lead_score, c.last_message_at
  FROM zapp.evolution_contacts c
  WHERE c.deleted_at IS NULL
    AND c.instance_name = v_instance
    AND (v_lead_status IS NULL OR c.lead_status = v_lead_status)
    AND (v_min_score IS NULL OR c.lead_score >= v_min_score)
    AND (v_created_after IS NULL OR c.created_at >= v_created_after)
    AND (v_no_consent IS NOT TRUE OR (c.lgpd_consent_at IS NULL AND c.lgpd_opt_out_at IS NULL))
  ORDER BY c.last_message_at DESC NULLS LAST
  LIMIT p_limit OFFSET p_offset;
END;
$function$



